def transform(grid):
    """Shrink each 3x3 block to its non-background (5) color, else 0.

    The object marks are sparse and uniformly colored within each block;
    color 5 is background/noise. Majority of non-5 pixels determines cell.
    """
    from collections import Counter
    out = []
    for y in range(0, len(grid), 3):
        row = []
        for x in range(0, len(grid[0]), 3):
            colors = [grid[yy][xx]
                      for yy in range(y, min(y + 3, len(grid)))
                      for xx in range(x, min(x + 3, len(grid[0])))
                      if grid[yy][xx] != 5]
            row.append(Counter(colors).most_common(1)[0][0] if colors else 0)
        out.append(row)
    return out", "exit_code": 0, "error": null}
